import sys
content = sys.stdin.read()

# Check phase lines have month spans
phases = ['1\ub2e8\uacc4', '2\ub2e8\uacc4', '3\ub2e8\uacc4']
expected_months = ['3\uac1c\uc6d4', '3\uac1c\uc6d4', '1\uac1c\uc6d4']

for phase, expected in zip(phases, expected_months):
    pattern = phase + r': .*?\((\d+\uac1c\uc6d4)\)'
    import re
    match = re.search(pattern, content)
    if match:
        found = match.group(1)
        if found == expected:
            print(f'\u2713 {phase}: {found} (correct)')
        else:
            print(f'\u2717 {phase}: {found} (expected {expected})')
    else:
        print(f'\u2717 {phase}: No month span found')

# Check lineSegArray removed from modified paragraphs (id 1,2,3,4)
paragraphs = re.findall(r'<hp:p id=\"(\d+)\"[^>]*>.*?(<hp:linesegarray\s*/>)?.*?</hp:p>', content, re.DOTALL)
for p_id, has_line in paragraphs:
    if p_id in ['1', '2', '3', '4']:
        if not has_line:
            print(f'\u2713 Paragraph {p_id}: lineSegArray removed')
        else:
            print(f'\u2717 Paragraph {p_id}: lineSegArray still present')
    elif p_id == '0':
        if has_line:
            print(f'\u2713 Paragraph {p_id}: lineSegArray preserved (unmodified)')
        else:
            print(f'\u2717 Paragraph {p_id}: lineSegArray missing (should be preserved)')
"
